using Microsoft.UI.Xaml.Automation;
using Microsoft.UI.Xaml.Controls;
using Ovi.Screenshot.Capture;
using Ovi.Screenshot.Native;
using Ovi.Screenshot.Services;
using Ovi.Screenshot.Views;
using Windows.ApplicationModel.DataTransfer;

namespace Ovi.Screenshot.Testing;

// All files are generated by the existing recording fixture and this test.
internal static class VideoPreviewSmoke
{
    internal static async Task VerifyAsync(string sourceVideo, string directory, Win32.Rect workArea)
    {
        Directory.CreateDirectory(directory);
        var storage = new CaptureStorage(directory);
        var savedRecording = await storage.SaveRecordingAsync(sourceVideo);
        string original = savedRecording.Path;
        string savedCopy = Path.Combine(directory, "independent.mp4");
        File.Copy(original, savedCopy);
        byte[] expected = await File.ReadAllBytesAsync(original);
        int fileDeletes = 0, payloadAttempts = 0, videoDeleted = 0;
        VideoPreview video = await VideoPreview.CreateAsync(original, workArea, async () =>
        {
            fileDeletes++;
            await savedRecording.DeleteAsync();
        });
        byte[] thumbnailPixels = video.Thumbnail.PreviewRgba;
        Require(thumbnailPixels.Length >= 4 && thumbnailPixels[3] != 0,
            "The decoded recording thumbnail was transparent or empty.");
        var package = new DataPackage();
        await video.PrepareDataAsync(package);
        var data = package.GetView();
        var items = await data.GetStorageItemsAsync();
        Require(items.Count == 1 && data.Contains(StandardDataFormats.StorageItems) && !data.Contains(StandardDataFormats.Bitmap),
            "Recording drag/copy did not provide exactly one video file.");
        string exported = items[0].Path;
        byte[] exportedBytes = await File.ReadAllBytesAsync(exported);
        Require(!StringComparer.OrdinalIgnoreCase.Equals(exported, original) &&
            expected.AsSpan().SequenceEqual(exportedBytes), "Recording export is not an independent MP4.");

        var stack = new PreviewStack(async capture =>
        {
            if (ReferenceEquals(capture, video.Thumbnail) && ++payloadAttempts == 1)
                throw new IOException("Synthetic thumbnail cleanup failure.");
            await capture.DeleteAsync();
        });
        stack.VideoDeleted += deleted => { if (ReferenceEquals(deleted, video)) videoDeleted++; };
        try
        {
            stack.Show(video);
            byte[] pixels = new byte[80 * 48 * 4];
            for (int index = 3; index < pixels.Length; index += 4) pixels[index] = 255;
            var screenshot = CaptureImageFactory.Create(new CapturedDisplay(80, 48, pixels),
                new PixelSelection(0, 0, 80, 48), workArea);
            var savedScreenshot = await storage.SaveScreenshotAsync(await screenshot.ReadPngAsync());
            string screenshotPath = savedScreenshot.Path;
            string independentImage = Path.Combine(directory, "independent.png");
            File.Copy(screenshotPath, independentImage);
            int screenshotDeletes = 0;
            stack.Show(screenshot, async () =>
            {
                screenshotDeletes++;
                if (screenshotDeletes == 1) throw new IOException("Synthetic saved screenshot deletion failure.");
                await savedScreenshot.DeleteAsync();
            }, screenshotPath);
            stack.Show(screenshot with { });
            Require(stack.SavedPath(screenshot with { }) == screenshotPath &&
                stack.IsSavedFile(screenshot with { }, screenshotPath) && !stack.IsSavedFile(screenshot, independentImage),
                "Autosaved screenshot identity was not preserved for Save As and clones.");
            Require(stack.Windows.Count == 3 && stack.Windows[0].Video == video,
                "Screenshot and recording thumbnails did not share the preview stack.");
            var recording = stack.Windows[0];
            var surface = (Grid)recording.Content;
            Require(surface.Children.OfType<Border>().Any(border => AutomationProperties.GetAutomationId(border) == "RecordingPlayBadge"),
                "Recording thumbnail did not show its play indicator.");

            await recording.DeleteAsync();
            Require(!File.Exists(original) && File.Exists(savedCopy) && File.Exists(exported) &&
                !video.IsDeleted && !recording.IsClosed && videoDeleted == 0 && fileDeletes == 1,
                "A failed thumbnail cleanup lost the recording preview or independent copies.");
            await recording.DeleteAsync();
            byte[] retainedBytes = await File.ReadAllBytesAsync(exported);
            Require(video.IsDeleted && recording.IsClosed && videoDeleted == 1 && fileDeletes == 1 &&
                expected.AsSpan().SequenceEqual(retainedBytes),
                "Retrying deletion repeated the owned-file deletion or removed a published copy.");

            var image = stack.Windows.First(window => ReferenceEquals(window.Capture.PngStorageIdentity, screenshot.PngStorageIdentity));
            await image.DeleteAsync();
            Require(File.Exists(screenshotPath) && !screenshot.IsDeleted && stack.Windows.Count == 2,
                "A failed saved screenshot deletion discarded its preview.");
            await image.DeleteAsync();
            Require(!File.Exists(screenshotPath) && screenshot.IsDeleted && stack.Windows.Count == 0 && File.Exists(independentImage),
                "Retrying screenshot deletion lost an independent copy or left shared previews open.");
        }
        finally
        {
            await stack.ShutdownAsync();
            // The generated test export was never put on the real clipboard or dragged.
            File.Delete(exported);
        }
    }

    private static void Require(bool condition, string message)
    {
        if (!condition) throw new InvalidOperationException(message);
    }
}
